public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // DFS to calculate minimum time
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
    int total = 0;
    for (int neighbor : graph.get(node)) {
        if (neighbor == parent) continue;
        int childTime = dfs(neighbor, node, graph, hasApple);
        if (childTime > 0 || hasApple[neighbor]) {
            total += childTime + 2;
        }
    }
    return total;
}
