public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) {
        return result;
    }

    // Pairs of digits that are center symmetric
    // When rotated 180 degrees, they map to each other
    // 0->0, 1->1, 6->9, 8->8, 9->6
    char[] leftDigits = {'0', '1', '6', '8', '9'};
    char[] rightDigits = {'0', '1', '9', '8', '6'};

    if (n % 2 == 0) {
        // Even length: build from both ends
        buildEven(n, 0, new char[n], leftDigits, rightDigits, result);
    } else {
        // Odd length: build from both ends with a center digit
        buildOdd(n, 0, new char[n], leftDigits, rightDigits, result);
    }

    return result;
}

private static void buildEven(int n, int depth, char[] chars, char[] leftDigits, char[] rightDigits, List<String> result) {
    if (depth == n / 2) {
        // Check if the number starts with 0 (only "0" is valid for n=1, but for even n>0, leading zero is not allowed)
        // For even length, if n > 0 and first char is '0', skip
        if (n > 0 && chars[0] == '0') {
            return;
        }
        result.add(new String(chars));
        return;
    }

    for (int i = 0; i < leftDigits.length; i++) {
        chars[depth] = leftDigits[i];
        chars[n - 1 - depth] = rightDigits[i];
        buildEven(n, depth + 1, chars, leftDigits, rightDigits, result);
    }
}

private static void buildOdd(int n, int depth, char[] chars, char[] leftDigits, char[] rightDigits, List<String> result) {
    if (depth == n / 2) {
        // Place the center digit
        char[] centerDigits = {'0', '1', '8'};
        for (char c : centerDigits) {
            chars[depth] = c;
            // Check if the number starts with 0
            if (n > 0 && chars[0] == '0') {
                continue;
            }
            result.add(new String(chars));
        }
        return;
    }

    for (int i = 0; i < leftDigits.length; i++) {
        chars[depth] = leftDigits[i];
        chars[n - 1 - depth] = rightDigits[i];
        buildOdd(n, depth + 1, chars, leftDigits, rightDigits, result);
    }
}
