public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the cross product to check if the three points are collinear
    // If the cross product is zero, the points are collinear (not a boomerang)
    // Cross product = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)
    int crossProduct = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);

    return crossProduct != 0;
}
